# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    total = sum(count for symbol, count in payload['runs'])
    def bound(index):
        return max(0, min(total, index))
    results = []
    for query in payload['slices']:
        start, stop = bound(query['start']), bound(query['stop'])
        selected, position = [], 0
        if stop > start:
            for symbol, count in payload['runs']:
                overlap = max(0, min(position + count, stop) - max(position, start))
                if overlap:
                    if selected and selected[-1][0] == symbol:
                        selected[-1][1] += overlap
                    else:
                        selected.append([symbol, overlap])
                position += count
        results.append(selected)
    return results

